ALTER TABLE "remote_surfaces" ADD CONSTRAINT "remote_surfaces_public_configuration_check" CHECK (("remote_surfaces"."kind" = 'browser' AND jsonb_typeof("remote_surfaces"."configuration") = 'object' AND ("remote_surfaces"."configuration"->>'kind') = 'browser' AND "remote_surfaces"."configuration" ? 'profileId' AND "remote_surfaces"."configuration" - 'kind' - 'profileId' = '{}'::jsonb AND jsonb_typeof("remote_surfaces"."configuration"->'profileId') IN ('string', 'null')) OR ("remote_surfaces"."kind" = 'desktop' AND "remote_surfaces"."configuration" = '{"kind":"desktop"}'::jsonb));
